use std::alloc::{Allocator, Layout};
use std::ptr::NonNull;

struct MyAlloc;

unsafe impl Allocator for MyAlloc {
    fn allocate(&self, l: Layout) -> Result<NonNull<[u8]>, std::alloc::AllocError> {
        NonNull::new(unsafe { std::alloc::alloc(l) })
            .map(|p| NonNull::slice_from_raw_parts(p, l.size()))
            .ok_or(std::alloc::AllocError)
    }

    unsafe fn deallocate(&self, p: NonNull<u8>, l: Layout) {
        unsafe { std::alloc::dealloc(p.as_ptr(), l) }
    }
}

fn foo<T>(_: std::vec::IntoIter<T, MyAlloc>) {}
```
