### Example 1
```rust
struct NotConstDestruct;

impl Drop for NotConstDestruct {
    fn drop(&mut self) {}
}

pub const _: () = {
    let mut a = Some(NotConstDestruct); //~ ERROR destructor of
    let b = NotConstDestruct;
    let p = &raw mut a;
    let x = unsafe { std::ptr::read(p) };
    std::mem::forget(a);
    std::mem::forget(x);
    a = None;
    unsafe { std::ptr::write(p, Some(b)) };
};
```
This should be fixed by https://github.com/rust-lang/rust/pull/164081.

### Example 2
```rust
use std::num::NonZero;

#[repr(transparent)]
struct NotConstDestruct(NonZero<u8>);

impl Drop for NotConstDestruct {
    fn drop(&mut self) {
        eprintln!("this is not const");
    }
}

enum MyOpt {
    None(()),
    Some(NotConstDestruct),
}

const _: () = {
    assert!(std::mem::size_of::<MyOpt>() == 1);
    let mut x = MyOpt::None(());
    let ptr = match x {
        MyOpt::None(ref mut field) => field as *mut (),
        _ => unreachable!(),
    };
    unsafe { ptr.cast::<u8>().write(1) };
};
```
See [here](https://github.com/rust-lang/rust/pull/164088#discussion_r4237993679) for why this happens. There is no fix yet.

