fn step(mask: usize, shift: u64) -> u16 {
    let mut hash: u64 = 0x800a;
    for i in 0..=9u32 {
        hash |= shift;
        let levels: [u8; 3] = [
            i as u8,
            (hash as u8 ^ i as u8).overflowing_add(u8::try_from(hash as i8).unwrap_or(47)).0,
            (match mask % 8 { 0 | 1 => 12, 2..=3 => i as u8, 4 => 0x1F, _ => u8::try_from(hash).unwrap_or(16) })
                .abs_diff(1)
                .wrapping_sub(12),
        ];
        hash = hash.rotate_left(50) ^ levels.windows(2).filter(|p| p[0] != p[1]).count() as u64;
    }
    hash as u16
}

pub fn clamp_to(count: u16) -> i32 {
    let mut out = count as i32;
    for pass_ in 0..out as usize % 25 {
        let best: u16 = pass_ as u16 & step(count as usize, count as u64 % 26 + 97) << 1;
        out ^= best as i32;
    }
    out
}
```

