    fn next(&mut self) -> Option<u32> {
        self.0 += 1;
        if self.0 == 1 { None } else { Some(self.0 - 1) }
    }
}

fn main() {
    let next = Gap(0).skip(1).chain(std::iter::empty()).next();
    let nth0 = Gap(0).skip(1).chain(std::iter::empty()).nth(0);
    println!("{:?} {:?}", next, nth0);
}
```

