body_text:
Based on variant analysis of https://github.com/rust-lang/rust/issues/164574.

```rs
// crate-a-padding.rs
use std::panic::Location;
pub const N: usize = Location::caller().file().len();

#[inline(never)]
pub fn fill(buf: &mut [u8; N]) {
    buf.fill(0x41);
}

pub fn n() -> usize {
    N
}
```

```rs
// crate-b-padding.rs
fn main() {
    println!("N here = {}, N in crate a = {}", a::N, a::n());
    let after = [7u8; 64];
    let mut buf = [0u8; a::N];
    let before = [7u8; 64];
    a::fill(&mut buf);
    println!("buf    {:?}", buf);
    println!("after  {:?}", after);
    println!("before {:?}", before);
}
```
The location detail being rewritten differently in the two crates causes a mismatch between the constant value when evaluated in the first and second crate.
```sh
$ rustc --crate-type rlib -Zlocation-detail=none crate-a-padding.rs -o liba.rlib && \
rustc -Zlocation-detail=file,line,column --extern a=liba.rlib crate-b-padding.rs -o b && \
./b

