Live Reproducer: [playground (nightly, debug)](https://play.rust-lang.org/?version=nightly&mode=debug&edition=2024&gist=ae4b1ecd9bdd73bd0af75ac3a6e5acf7)

With `#![feature(async_drop)]`, `async_drop_in_place` on a future that is suspended in the async drop of `_b` drops `a` as well, although `a` was moved into `_b`. The `Box` is freed twice.

```rust
#![feature(async_drop)]
#![allow(incomplete_features)]
use std::future::{AsyncDrop, Future, async_drop_in_place, poll_fn};
use std::mem::ManuallyDrop;
use std::pin::{Pin, pin};
use std::task::{Context, Poll, Waker};

async fn yield_now() {
    let mut yielded = false;
    poll_fn(|_| match std::mem::replace(&mut yielded, true) {
        false => Poll::Pending,
        true => Poll::Ready(()),
    })
    .await
}

struct A(Box<u32>);
impl Drop for A {
    fn drop(&mut self) {}
}
impl AsyncDrop for A {
    async fn drop(self: Pin<&mut Self>) {
        println!("async drop");
        yield_now().await;
    }
}

async fn f() {
    let a = A(Box::new(0));
    yield_now().await;
    let _b = a;
}

fn main() {
    let mut cx = Context::from_waker(Waker::noop());
    let mut f = ManuallyDrop::new(f());
    let mut f = unsafe { Pin::new_unchecked(&mut *f) };
    let _ = f.as_mut().poll(&mut cx); // suspended at `yield_now().await`
    let _ = f.as_mut().poll(&mut cx); // suspended in the async drop of `_b`
    let mut d = pin!(unsafe { async_drop_in_place(f.get_unchecked_mut()) });
    while d.as_mut().poll(&mut cx).is_pending() {}
}
```

