// PROCESS_MEMORY_COUNTERS. `PagefileUsage` is the process's commit charge.
#[repr(C)]
#[derive(Default)]
struct ProcessMemoryCounters {
    cb: u32,
    page_fault_count: u32,
    peak_working_set_size: usize,
    working_set_size: usize,
    pool_usage: [usize; 4],
    pagefile_usage: usize,
    peak_pagefile_usage: usize,
}

#[link(name = "kernel32")]
extern "system" {
    fn K32GetProcessMemoryInfo(process: *mut c_void, counters: *mut ProcessMemoryCounters, cb: u32) -> i32;
}

fn main() {
    let mib: u64 = std::env::args().nth(1).map_or(1024, |a| a.parse().unwrap());
    // The compiler itself, not rustup's proxy.
    let sysroot = Command::new("rustc").args(["--print", "sysroot"]).output().unwrap().stdout;
    let rustc = Path::new(String::from_utf8(sysroot).unwrap().trim()).join("bin").join("rustc.exe");
    let run = |args: &str| Command::new(&rustc).args(args.split(' ')).spawn().unwrap();

    // A dependency with a large rlib, and a crate that only type-checks against it.
    fs::File::create("blob.bin").unwrap().set_len(mib << 20).unwrap();
    fs::write("big.rs", r#"pub static DATA: &[u8] = include_bytes!("blob.bin");"#).unwrap();
    fs::write("user.rs", "pub fn len() -> usize { big::DATA.len() }").unwrap();
    assert!(run("--edition 2021 --crate-type rlib big.rs").wait().unwrap().success());
    let mut child = run("--edition 2021 --crate-type rlib --emit metadata --extern big=libbig.rlib user.rs");
    assert!(child.wait().unwrap().success());

    let mut memory = ProcessMemoryCounters::default();
    memory.cb = std::mem::size_of::<ProcessMemoryCounters>() as u32;
    assert!(unsafe { K32GetProcessMemoryInfo(child.as_raw_handle(), &mut memory, memory.cb) } != 0);
