    print!("{}", String::from_utf8_lossy(&version));
    println!("libbig.rlib:              {:>5} MiB", fs::metadata("libbig.rlib").unwrap().len() >> 20);
    println!("rustc's peak commit:      {:>5} MiB", memory.peak_pagefile_usage >> 20);
    println!("rustc's peak working set: {:>5} MiB", memory.peak_working_set_size >> 20);
}
