With `#![feature(async_drop)]`, when a suspended future is dropped asynchronously, the first poll of its drop runs with the `Context` that the future was last polled with, not with the one passed to the poll that drops it. If that `Context` is gone, the async destructors get a dangling `&mut Context`, in safe code. Miri reports UB.

```rust
#![feature(async_drop)]
#![allow(incomplete_features)]
use std::cell::Cell;
use std::future::{AsyncDrop, Future, poll_fn};
use std::pin::{Pin, pin};
use std::task::{Context, Poll, Waker};

thread_local! {
    static CURRENT: Cell<usize> = const { Cell::new(0) };
}

struct A;
impl Drop for A {
    fn drop(&mut self) {}
}
impl AsyncDrop for A {
    async fn drop(self: Pin<&mut Self>) {
        poll_fn(|cx| {
            if cx as *mut Context<'_> as usize == CURRENT.get() {
                println!("async drop: current context");
            } else {
                println!("async drop: stale context");
            }
            Poll::Ready(())
        })
        .await;
    }
}

async fn f() {
    let _a = A;
    std::future::pending::<()>().await;
}

async fn g() {
    let mut f = pin!(f());
    let _ = f.as_mut().poll(&mut Context::from_waker(Waker::noop()));
} // the suspended `f` is dropped asynchronously here

fn main() {
    let mut cx = Context::from_waker(Waker::noop());
    CURRENT.set(&mut cx as *mut Context<'_> as usize);
    let _ = pin!(g()).poll(&mut cx);
}
```

