Live Reproducer: [playground (nightly, debug)](https://play.rust-lang.org/?version=nightly&mode=debug&edition=2024&gist=d51eb2f136a6d9bdfdc2bd852bab2503)

With `#![feature(async_drop)]`, the values that a future still owns while it is suspended in an async drop don't look like being considered for its auto traits. `f()` is accepted as `Send` although, while suspended in the async drop of `A`, it owns an `Rc` (the second field of `_t`). Finishing it on another thread races with the main thread's clone.

```rust
#![feature(async_drop)]
#![allow(incomplete_features)]
use std::future::{AsyncDrop, Future, poll_fn};
use std::pin::Pin;
use std::rc::Rc;
use std::task::{Context, Poll, Waker};

struct A;
impl Drop for A {
    fn drop(&mut self) {}
}
impl AsyncDrop for A {
    async fn drop(self: Pin<&mut Self>) {
        let mut yielded = false;
        poll_fn(|_| match std::mem::replace(&mut yielded, true) {
            false => Poll::Pending,
            true => Poll::Ready(()),
        })
        .await
    }
}

thread_local! {
    static RC: Rc<u32> = Rc::new(0);
}

async fn f() {
    let _t = (A, RC.with(Rc::clone));
}

fn assert_send<T: Send>(t: T) -> T {
    t
}

fn main() {
    let mut f = Box::pin(assert_send(f()));
    let _ = f.as_mut().poll(&mut Context::from_waker(Waker::noop())); // in the async drop of `A`
    println!("{}", RC.with(Rc::strong_count)); // `f` still owns a clone
    let t = std::thread::spawn(move || {
        let _ = f.as_mut().poll(&mut Context::from_waker(Waker::noop())); // drops the `Rc`
    });
    let _c = RC.with(Rc::clone);
    t.join().unwrap();
}
```

