No dependencies, std only. `rustc --edition=2024 --crate-type=lib --emit=metadata repro.rs`:

```rust
pub trait Module {}
pub trait HasComponent<I: ?Sized> {}
pub trait Component<M> {
    type Interface: ?Sized;
}

pub struct Container;
impl Module for Container {}

pub trait T0 {}
pub struct C0;
impl<M: Module> Component<M> for C0 { type Interface = dyn T0; }
impl HasComponent<<C0 as Component<Container>>::Interface> for Container {}
pub trait T1 {}
pub struct C1;
impl<M: Module + HasComponent<dyn T0>> Component<M> for C1 { type Interface = dyn T1; }
impl HasComponent<<C1 as Component<Container>>::Interface> for Container {}
